INSERT INTO products (category_id, name, slug, description, price, discount, stock, active, featured, main_image_url) VALUES
('c3333333-3333-3333-3333-333333333333', 'press aplique 134 x 89 caja dat x 2400u. ref: 2500', 'press-aplique-134-x-89-caja-dat-x-2400u-ref-2500-1709', 'Press Aplique 134 x 89 Caja DAT x 2400u. Ref: 2500: Solución Eficiente para tus Necesidades de Empaque Alta calidad y resistencia en cada aplicación para tu industria El Press Aplique 134 x 89 Caja DAT x 2400u. Ref: 2500 está diseñado para ofrecerte la máxima calidad y resistencia en procesos de empaque. Con medidas de 134 x 89 mm, estos aplicadores son ideales para una amplia variedad de usos industriales, garantizando un sellado seguro y eficiente. Cada caja contiene 2400 unidades, lo que te permite contar con un suministro constante para tu línea de producción. Su diseño robusto y fiable asegura un rendimiento óptimo, permitiendo realizar aplicaciones rápidas y precisas para facilitar tu trabajo. Ideal para empresas que buscan optimizar sus procesos de empaque sin sacrificar calidad.', 269709.00, 20, 39, true, false, 'https://www.abastece.co/abastece/images/1709.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Press Aplique 134 X 89 Carpeta Dat X 150u.  Ref: 2000', 'press-aplique-134-x-89-carpeta-dat-x-150u-ref-2000-1737', 'Press Aplique 134 x 89 mm - Carpeta DAT x 150 Unidades (Ref: 2000) ¡Formato extra grande para una señalización industrial y administrativa clara! El Press Aplique Ref. 2000 es un insumo técnico de dimensiones superiores, diseñado para aquellos procesos que requieren una visualización de datos extensa y detallada. Con un formato de 134 x 89 mm, estos rótulos ofrecen el espacio suficiente para descripciones técnicas completas, instrucciones de manejo o una rotulación de gran formato en cajas de archivo muerto y contenedores. Su adhesivo de alta adherencia garantiza que la etiqueta permanezca plana y segura sobre superficies de cartón, plástico o metal. Esta presentación de 150 unidades es la herramienta ideal para centros de acopio, bodegas y archivos centrales que necesitan estandarizar su identificación con un producto robusto, profesional y de fácil lectura.', 30812.00, 20, 45, true, false, 'https://www.abastece.co/abastece/images/1737.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Press Aplique 13mm X1064 Rotulos Sobre Rojo Ref 1192', 'press-aplique-13mm-x1064-rotulos-sobre-rojo-ref-1192-9104', 'Presentamos el Press Aplique 13 mm x 1064: Rotulos sobre Rojo Ref: 1192 Diseño Impactante para tus Etiquetas El Press Aplique 13 mm x 1064 es ideal para quienes buscan crear rotulos sobre un vibrante fondo rojo. Este producto combina facilidad de uso y calidad, permitiendote personalizar etiquetas que capturan la atencion. Con la referencia 1192, da un nuevo giro a tus proyectos con rotulos que destacan y transmiten tu mensaje de manera efectiva.', 5313.00, 20, 39, true, false, 'https://www.abastece.co/abastece/images/9104.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Press Aplique 13mm x1064 Rotulos Sobre Verde Ref 1193', 'press-aplique-13mm-x1064-rotulos-sobre-verde-ref-1193-9105', 'Press Aplique 13mm x1064 Rótulos Sobre Verde - Ref. 1193 Rótulos Versátiles para Organizar con Estilo Descubre el Press Aplique 13mm x1064 Rótulos Sobre Verde (Referencia 1193). Diseñados para ofrecer una solución de etiquetado práctica y atractiva, estos rótulos son ideales para organizar tus documentos, carpetas o productos. Con su vibrante color verde, añaden un toque fresco y dinámico a cualquier proyecto, asegurando que tu información sea clara y fácil de identificar.', 5313.00, 20, 31, true, false, 'https://www.abastece.co/abastece/images/9105.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Press Aplique 16 Mm  X 714 Rotulos Sobre Verde Ref 1183', 'press-aplique-16-mm-x-714-rotulos-sobre-verde-ref-1183-9908', 'Press Aplique 16 mm x 714: Rótulos sobre Verde para una Organización Clara Destaca tu Información con Estilo y Eficiencia Presentamos el Press Aplique de 16 mm x 714, con rótulos sobre verde (Ref: 1183). Perfectos para etiquetar, marcar y organizar, estos rótulos son ideales para oficinas, escuelas y el hogar. Su color vibrante no solo aporta un toque de frescura, sino que también asegura que tu información sea fácilmente visible. Con su adhesivo de alta calidad, tendrás la tranquilidad de que se mantendrán en su lugar. ¡Haz que la organización sea efectiva y atractiva!', 5312.00, 20, 28, true, false, 'https://www.abastece.co/abastece/images/9908.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Press Aplique 16 Mm X 714 Rotulos Sobre Amarillo  Ref 1180', 'press-aplique-16-mm-x-714-rotulos-sobre-amarillo-ref-1180-9098', 'Cinta para Enmascarar 18x40 3M y Press Aplique 16mm x 714 Rótulos sobre Amarillo Ref 1180 Productos de Alta Calidad para Tus Proyectos de Pintura y Etiquetado Descubre la Cinta para Enmascarar 18x40 3M, la herramienta ideal para lograr líneas perfectas y proteger tus superficies durante la pintura. Con un tamaño de 18 mm de ancho y 40 metros de longitud, ofrece una adhesión fuerte y una fácil remoción sin residuos. Además, te presentamos el Press Aplique 16mm x 714 Rótulos sobre Amarillo Ref 1180, diseñado para facilitar la aplicación de etiquetas de alta calidad en diversas superficies. Perfecto para identificar productos y mantener tus proyectos organizados, con una durabilidad excepcional y visibilidad clara gracias a su fondo amarillo brillante.', 5313.00, 20, 34, true, false, 'https://www.abastece.co/abastece/images/9098.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Press Aplique 16mm X714 Rotulos Sobre Rojo  Ref: 1182', 'press-aplique-16mm-x714-rotulos-sobre-rojo-ref-1182-9097', 'Press Aplique 16 mm - Rojo (Ref: 1182) - Sobre x714 Rótulos ¡Señalización de alto impacto y control visual para procesos de calidad! El Press Aplique Ref. 1182 es un insumo técnico de marcación circular diseñado para ofrecer una identificación visual inmediata y efectiva. Con un diámetro de 16 mm y un intenso color rojo, es la herramienta ideal para señalizar alertas, errores en control de calidad, estados de urgencia o categorías críticas en sistemas de inventario. Su adhesivo de alta estabilidad garantiza una fijación segura sobre múltiples superficies, evitando desprendimientos durante la manipulación de documentos o productos. Esta presentación de 714 rótulos es indispensable para entornos industriales, laboratorios y departamentos administrativos que requieren una gestión visual dinámica, profesional y altamente organizada.', 5312.00, 20, 25, true, false, 'https://www.abastece.co/abastece/images/9097.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Press Aplique 195 X 135 Carpeta Dat X 66u.  Ref: 2232', 'press-aplique-195-x-135-carpeta-dat-x-66u-ref-2232-1959', 'Press Aplique 195 x 135 mm - Carpeta DAT x 66 Unidades (Ref: 2232) ¡Máxima superficie de rotulación para una organización de gran formato! El Press Aplique Ref. 2232 es un insumo técnico de dimensiones excepcionales, diseñado para procesos de identificación que requieren la exposición de gran cantidad de datos o señalización de alta visibilidad. Con un formato de 195 x 135 mm, estos rótulos ofrecen una superficie amplia, ideal para crear portadas de expedientes, señalizar cajas de archivo de gran volumen o rotular maquinaria y activos fijos con instrucciones detalladas. Su adhesivo de grado profesional asegura una fijación firme y duradera en superficies lisas o porosas, manteniendo la legibilidad y el orden en entornos de alta exigencia. Esta presentación de 66 unidades es la solución definitiva para centros de documentación masiva, departamentos de logística y bodegas industriales que buscan un estándar de rotulación claro, robusto y profesional.', 30812.00, 20, 40, true, false, 'https://www.abastece.co/abastece/images/1959.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Press Aplique 19mm x270 Rotulos Sobre Plateado Ref 1176', 'press-aplique-19mm-x270-rotulos-sobre-plateado-ref-1176-3041', 'Press Aplique 19mm x 270 Rotulos - Sobre Plateado Ref 1176 Identificacion y organizacion con un acabado profesional Los rotulos Press Aplique de 19mm x 270 unidades en color plateado son ideales para etiquetar y organizar documentos, carpetas y otros materiales de oficina. Su adhesivo de alta calidad garantiza una fijacion duradera. ¡Optimiza tu organizacion con etiquetas practicas y elegantes!', 5313.00, 20, 49, true, false, 'https://www.abastece.co/abastece/images/3041.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Press Aplique 20 X 8 Mm 1.350 Rotulos Sobre Verde Ref: 1133', 'press-aplique-20-x-8-mm-1350-rotulos-sobre-verde-ref-1133-9520', 'Press Aplique 20 x 8 mm - Verde (Ref: 1133) - Sobre x1350 Rótulos ¡Codificación técnica y organización visual para procesos de precisión! El Press Aplique Ref. 1133 es un insumo de rotulación técnica en formato pequeño, diseñado para sistemas de clasificación que requieren una identificación clara en espacios reducidos. Con dimensiones de 20 x 8 mm y un color verde distintivo, es ideal para señalizar estados aprobados, procesos completados o inventarios verificados. Su adhesivo de alta calidad garantiza una fijación estable sobre diversas superficies, evitando el desprendimiento accidental. Esta presentación de 1350 unidades es la solución profesional para departamentos de control de calidad, laboratorios y centros de documentación que operan bajo estándares de gestión visual y organización sistemática.', 272644.00, 20, 18, true, false, 'https://www.abastece.co/abastece/images/9520.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Press Aplique 20x8 mm 1.350 Rotulos Sobre Blanco Ref: 1134', 'press-aplique-20x8-mm-1350-rotulos-sobre-blanco-ref-1134-1758', 'Press Aplique 20x8 mm - 1.350 Rótulos Sobre Blanco Ref 1134 Rótulos de Alta Calidad para Aplicación Precisa y Duradera Los Rótulos Press Aplique 20x8 mm (Ref. 1134) son ideales para todo tipo de etiquetas que requieren un acabado profesional y duradero. Este paquete incluye 1.350 rótulos sobre fondo blanco, perfectos para uso en oficinas, almacenes o cualquier entorno que necesite organización y etiquetado claro. Con una aplicación fácil y precisa, estos rótulos son la opción ideal para mantener tus productos y documentos ordenados y bien identificados.', 4999.00, 20, 39, true, false, 'https://www.abastece.co/abastece/images/1758.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Press Aplique 215,9x139,7 Caja Laser 800u. Ref:3629', 'press-aplique-2159x1397-caja-laser-800u-ref3629-72155', '¡Identificación y etiquetado a gran escala! Press Aplique 215,9 x 139,7 mm - Caja Láser por 800 Unidades - Ref: 3629 Etiquetas adhesivas Press Aplique de 215,9 x 139,7 mm, presentadas en caja láser con 800 unidades. Referencia 3629, ideales para impresión profesional, logística y organización de documentos o productos.', 208042.00, 20, 28, true, false, 'https://www.abastece.co/abastece/images/72155.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Press Aplique 215.9 X 139.7 Carpeta Laser X 60 Rótulos  Ref: 3128', 'press-aplique-2159-x-1397-carpeta-laser-x-60-rotulos-ref-3128-71244', 'Press Aplique 215.9 x 139.7 mm - Carpeta por 60 Rótulos (Ref. 3128) Los rótulos Press Aplique Ref. 3128 son etiquetas autoadhesivas de gran tamaño, ideales para la identificación de cajas de archivo, señalización industrial y la creación de guías de envío de media carta. Con dimensiones de 215.9 x 139.7 mm, están optimizados para funcionar perfectamente en impresoras láser e inkjet, garantizando un paso fluido sin atascos y una fijación de tinta profesional. Su presentación en carpeta de 60 unidades es la solución práctica para proyectos que requieren etiquetas de alta visibilidad, gran formato y una adhesión resistente en diversas superficies de cartón, plástico o papel.', 32681.00, 20, 41, true, false, 'https://www.abastece.co/abastece/images/71244.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Press Aplique 215.9 x 279.4 x 400u. Caja Laser Ref: 3628', 'press-aplique-2159-x-2794-x-400u-caja-laser-ref-3628-1343', 'Press Aplique 215.9 x 279.4 x 400u. Caja Laser Ref: 3628 Calidad y rendimiento superior para tus impresiones de gran volumen El Press Aplique 215.9 x 279.4 x 400u. Caja Laser Ref: 3628 es ideal para quienes necesitan realizar impresiones de gran formato con alta calidad. Con 400 unidades por caja, este producto está diseñado para impresoras láser, garantizando resultados nítidos y profesionales en cada uso, perfecto para empresas o proyectos de alto volumen.', 189697.00, 20, 19, true, false, 'https://www.abastece.co/abastece/images/1343.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Press Aplique 215.9x279.4mm Carpeta Laser X30R Ref:3129', 'press-aplique-2159x2794mm-carpeta-laser-x30r-ref3129-1344', 'Press Aplique 215.9 x 279.9 mm: Etiquetas para Carpeta Láser Organiza tus Documentos con Profesionalismo Descubre el Press Aplique de 215.9 x 279.9 mm, diseñado para carpetas láser (Ref: 3129). Con un paquete de 30 unidades, estas etiquetas te permiten personalizar y organizar tus documentos de manera efectiva. Su diseño fácil de usar asegura una aplicación rápida y precisa, ideal para oficinas, escuelas y proyectos personales. Dale un toque profesional a tus presentaciones y mantén todo en orden con estas prácticas etiquetas. ¡Haz que la organización sea un arte!', 32682.00, 20, 51, true, false, 'https://www.abastece.co/abastece/images/1344.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Press Aplique 22x16x540 Rotulos Sobre Verde Ref:1073', 'press-aplique-22x16x540-rotulos-sobre-verde-ref1073-9370', 'Explora el Press Aplique 22x16x540: Rotulos sobre Verde Ref: 1073 Etiquetas Vibrantes para Cada Ocasion El Press Aplique 22x16x540 es la opcion perfecta para quienes desean imprimir rotulos sobre un atractivo fondo verde. Con su diseño eficiente y facil manejo, este producto te permitira crear etiquetas personalizadas y llamativas. Con la referencia 1073, transforma tus ideas en impresionantes rotulos que destacan. ¡Haz que tus proyectos resalten!', 5313.00, 20, 17, true, false, 'https://www.abastece.co/abastece/images/9370.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Press Aplique 25 X 12  Caja Laser X 61600u. Ref: 3510', 'press-aplique-25-x-12-caja-laser-x-61600u-ref-3510-0506', '¡Encuentra todo para tus proyectos y oficina! Press Aplique 25 x 12 Caja Láser x 61.600u - Ref: 3510 Alta calidad y gran cantidad con el Press Aplique 25 x 12, presentado en caja láser con 61.600 unidades. Ideal para uso en oficinas, proyectos escolares o industriales que requieren materiales duraderos y confiables. Producto con referencia 3510 para fácil identificación y reposición.', 208042.00, 20, 46, true, false, 'https://www.abastece.co/abastece/images/0506.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Press Aplique 25 x 12 Carpeta Laser x4620 Rotulos Ref:3010', 'press-aplique-25-x-12-carpeta-laser-x4620-rotulos-ref3010-2444', 'Press Aplique 25 x 12 Carpeta Laser x4620 Rótulos Ref: 3010 Precisión y calidad para tus impresiones de rótulos El Press Aplique 25 x 12 Carpeta Laser x4620 Rótulos Ref: 3010 es ideal para realizar impresiones claras y duraderas. Con su diseño optimizado para usar con impresoras láser, este producto garantiza resultados de alta calidad en la creación de rótulos, etiquetas y más, perfectos para oficina o uso comercial.', 32682.00, 20, 52, true, false, 'https://www.abastece.co/abastece/images/2444.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Press Aplique 27 X 19 Sobre Azul X 360u. Ref: 1061', 'press-aplique-27-x-19-sobre-azul-x-360u-ref-1061-9041', 'Press Aplique 27 x 19 mm - Azul (Ref: 1061) - Sobre x360 Rótulos ¡Estandarización visual y control de procesos con acabado profesional! El Press Aplique Ref. 1061 es un insumo de rotulación técnica diseñado para facilitar la clasificación sistemática y el control visual en cualquier entorno operativo. Con un formato versátil de 27 x 19 mm y un color azul sólido, estos rótulos son ideales para la identificación de carpetas, categorización de productos en inventario o la señalización de documentos por dependencias. Su adhesivo de alta calidad garantiza una adherencia inmediata y duradera, evitando que la información se pierda por desprendimiento. Esta presentación de 360 unidades es la solución práctica y eficiente para oficinas, bibliotecas y departamentos de logística que buscan mantener un estándar de organización impecable y de fácil reconocimiento.', 4980.00, 20, 36, true, false, 'https://www.abastece.co/abastece/images/9041.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Press Aplique 32x16 Carpeta Laser x2880 Rotulos Ref 3140', 'press-aplique-32x16-carpeta-laser-x2880-rotulos-ref-3140-2192', 'Press Aplique 32x16 Carpeta Láser x2880 Rótulos Ref. 3140: Alta Calidad para tus Necesidades de Impresión Rótulos Personalizados y Precisión en Cada Impresión El **Press Aplique 32x16 Carpeta Láser x2880 Rótulos Ref. 3140** es la herramienta ideal para realizar impresiones de alta calidad y precisión en rótulos, etiquetas y otros materiales personalizados. Con un tamaño de 32x16 mm, estos rótulos están diseñados para ofrecer un acabado profesional en cada impresión, ya sea en la oficina, el hogar o en proyectos comerciales. Su compatibilidad con impresoras láser garantiza una calidad superior y colores nítidos y vibrantes en cada uso. Este paquete contiene 2880 rótulos, lo que te proporciona una gran cantidad de material para proyectos de etiquetado a gran escala, organización o branding. Cada rótulo es resistente, duradero y adecuado para una amplia variedad de aplicaciones, desde la identificación de productos hasta la creación de etiquetas personalizadas para eventos, productos o documentos. Aprovecha al máximo tu impresora láser con la **Carpeta Láser x2880 Rótulos Ref. 3140** y obtén resultados de alta calidad en cada proyecto.', 32682.00, 20, 32, true, false, 'https://www.abastece.co/abastece/images/2192.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Press Aplique 32x22 Carpeta Laser x1980 Rotulo Ref:3021', 'press-aplique-32x22-carpeta-laser-x1980-rotulo-ref3021-1669', 'Press Aplique 32 x 22: Etiquetas para Carpeta Láser x1980 Maximiza tu Organización con Rótulos Eficientes Te presentamos el Press Aplique de 32 x 22, ideal para carpetas láser (Ref: 3021), con un impresionante paquete de 1980 rótulos. Perfectos para etiquetar documentos, archivos y proyectos, estos rótulos te ayudarán a mantener todo organizado y de fácil acceso. Su calidad de impresión asegura que tu información sea clara y visible. Ideal para oficinas, escuelas y uso personal, ¡simplifica tu vida con una organización sin complicaciones!', 32682.00, 20, 39, true, false, 'https://www.abastece.co/abastece/images/1669.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Press Aplique 35.8 X 25.4 X1800u. Carpeta Laser Ref:3024', 'press-aplique-358-x-254-x1800u-carpeta-laser-ref3024-5435', 'Press Aplique 35.8 x 25.4 x 1,800 u. Carpeta Láser Ref: 3024 Precisión y calidad para etiquetado profesional El Press Aplique 35.8 x 25.4 es ideal para impresiones en carpeta láser, asegurando una adhesión duradera y de alta calidad. Con 1,800 unidades por caja, es perfecto para grandes volúmenes de trabajo. ¡Optimiza tu proceso de etiquetado con este producto confiable y eficiente!', 32681.00, 20, 35, true, false, 'https://www.abastece.co/abastece/images/5435.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Press Aplique 40 X 25 Sobre Blanco X 240 Rotulos Ref:1054', 'press-aplique-40-x-25-sobre-blanco-x-240-rotulos-ref1054-0935', 'Press Aplique 40 x 25 Sobre Blanco x 240 Rótulos Ref: 1054 Ilumina tu espacio con eficiencia y estilo El press aplique 40 x 25 sobre blanco con 240 rótulos ref. 1054 es ideal para quienes buscan una iluminación funcional y estética. Su diseño compacto y elegante en color blanco se adapta perfectamente a diferentes entornos, ofreciendo una luz suave y clara. Perfecto para oficinas, hogares o espacios comerciales, este aplique garantiza durabilidad, facilidad de instalación y un rendimiento eficiente.', 4999.00, 20, 39, true, false, 'https://www.abastece.co/abastece/images/0935.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Press Aplique 45 X4x5 Carpeta Laser X 600 Rótulos Ref: 3138', 'press-aplique-45-x4x5-carpeta-laser-x-600-rotulos-ref-3138-70434', 'Press Aplique 45 x 45 mm - Carpeta Láser x 600 Rótulos (Ref: 3138) ¡Simetría perfecta y tecnología láser para un etiquetado preciso! El Press Aplique Ref. 3138 es un insumo técnico de formato cuadrado diseñado para ofrecer una solución de etiquetado equilibrada y profesional. Con dimensiones de 45 x 45 mm, estos rótulos son ideales para la identificación de productos, sellado de empaques o rotulación de activos donde la estética y la claridad son fundamentales. Su superficie está optimizada para la tecnología de impresión láser, asegurando que el tóner se fije de manera uniforme para obtener textos nítidos y gráficos definidos. Gracias a su adhesivo de alta estabilidad térmica, las etiquetas no se deforman ni pierden adherencia durante el proceso de impresión. Esta presentación en carpeta de 600 rótulos es la opción preferida por agencias de publicidad, departamentos de logística y pymes que buscan versatilidad y calidad en sus procesos de identificación.', 30629.00, 20, 54, true, false, 'https://www.abastece.co/abastece/images/70434.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Press Aplique 48x12 Carpeta Laser x2640 Rotulos Ref:3035', 'press-aplique-48x12-carpeta-laser-x2640-rotulos-ref3035-2263', 'Press Aplique 48x12 Carpeta Láser x2640 Rótulos Ref: 3035: Rótulos Claros y Duraderos para tu Impresión Láser Rótulos de Alta Calidad para tus Proyectos de Impresión Láser Los Rótulos Press Aplique 48x12, con 2640 unidades en la Carpeta Láser Ref: 3035, son perfectos para aquellos que buscan rótulos duraderos y de alta calidad. Estos rótulos están diseñados específicamente para ser utilizados en impresoras láser, ofreciendo resultados nítidos y profesionales. Ideales para oficina, almacenes o cualquier área que requiera un etiquetado claro y eficiente. ¡Optimiza tu proceso de etiquetado con los rótulos Press Aplique!', 32681.00, 20, 33, true, false, 'https://www.abastece.co/abastece/images/2263.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Press Aplique 50 X 20 X 216 Rotulos Sobre Amarillo Ref: 1110', 'press-aplique-50-x-20-x-216-rotulos-sobre-amarillo-ref-1110-8910', 'Press Aplique 50 x 20 mm - Amarillo (Ref: 1110) - Sobre x216 Rótulos ¡Visibilidad inmediata y organización táctica para control de inventarios! El Press Aplique Ref. 1110 es un insumo técnico de señalización diseñado para destacar información crítica y optimizar la gestión visual en almacenes y oficinas. Con un formato rectangular de 50 x 20 mm y un color amarillo de alta visibilidad, estos rótulos son la herramienta perfecta para la codificación de estanterías, marcado de precios, identificación de lotes o señalización de alertas en procesos de despacho. Su adhesivo de alta adherencia garantiza una fijación segura sobre diversas superficies, manteniendo la rotulación intacta frente a la manipulación constante. Esta presentación en sobre de 216 unidades es ideal para comercios, áreas de logística y departamentos de archivo que buscan una solución de marcación manual rápida, duradera y profesional.', 5313.00, 20, 25, true, false, 'https://www.abastece.co/abastece/images/8910.jpg'),
