INSERT INTO products (category_id, name, slug, description, price, discount, stock, active, featured, main_image_url) VALUES
('c3333333-3333-3333-3333-333333333333', 'Resaltador Redondo Pelikan Mark 2 Amarillo Punta Biselada', 'resaltador-redondo-pelikan-mark-2-amarillo-punta-biselada-8691', 'Resalta Tu Creatividad con el Resaltador Pelikan Mark 2 de Colores Vibrantes Experimenta la Intensidad de los colores Diseño ergonómico ofrece una experiencia única de resaltado. Destaca con estilo y precisión, resaltando tus ideas de manera brillante Colores intensos, diseño cómodo y trazos precisos hacen que cada palabra cobre vida. Eleva tu creatividad y organización con esta herramienta imprescindible en tu escritorio.', 889.00, 20, 27, true, false, 'https://www.abastece.co/abastece/images/8691.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Resaltador Redondo Pelikan Mark 2 Anaranjado Punta Biselada', 'resaltador-redondo-pelikan-mark-2-anaranjado-punta-biselada-1041', 'Resaltador Redondo Anaranjado Punta Biselada - Precisión y Visibilidad Ideal para resaltar, subrayar y marcar con claridad El Resaltador Redondo Anaranjado con Punta Biselada es la herramienta perfecta para aquellos que necesitan precisión y un color vibrante. Su diseño redondo y la punta biselada permiten un marcado claro y eficaz en todo tipo de documentos. Ya sea para estudios, trabajo en oficina o proyectos creativos, este resaltador asegura que cada palabra importante resalte con intensidad. Su tinta de alta calidad proporciona una visibilidad excelente sin traspasar el papel, garantizando un uso cómodo y eficiente en todo momento.', 893.00, 20, 36, true, false, 'https://www.abastece.co/abastece/images/1041.jpg'),
('c3333333-3333-3333-3333-333333333333', 'Resaltador Redondo Pelikan Mark 2 Azul Punta Biselada', 'resaltador-redondo-pelikan-mark-2-azul-punta-biselada-0857', 'Descubre el Resaltador Redondo Azul con Punta Biselada La Herramienta Perfecta para Destacar tus Ideas El Resaltador Redondo Azul Punta Biselada es el compañero ideal para estudiantes, profesionales y creativos. Su diseño innovador y su vibrante color azul te permitiran resaltar lo mas importante en tus documentos, libros y notas. Con su punta biselada, puedes crear lineas finas o gruesas segun tus necesidades, asegurando que tu mensaje brille con claridad. ¡Haz que tus ideas destaquen hoy mismo!', 889.00, 20, 52, true, false, 'https://www.abastece.co/abastece/images/0857.jpg'),
